const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const req = $input.first().json ?? {};
const payload = req.body ?? req;
const ROOT = path.resolve(String($env.OPENCLAW_ASSET_SHARED_ROOT || '/data/openclaw-assets'));
const MAX_ASSETS = 500;
const SHA256_PATTERN = /^sha256:[a-f0-9]{64}$/;
const STRICT_SCHEMA = /^2\./.test(String(payload.schema_version || ''));

if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
  throw new Error('请求体必须是 JSON 对象');
}
if (!Array.isArray(payload.assets) || payload.assets.length === 0) {
  throw new Error('assets 必须是非空数组');
}
if (payload.assets.length > MAX_ASSETS) {
  throw new Error(`单任务资产数不能超过 ${MAX_ASSETS}`);
}

const headers = Object.fromEntries(Object.entries(req.headers ?? {}).map(([key, value]) => [
  String(key).toLowerCase(),
  Array.isArray(value) ? String(value[0] ?? '') : String(value ?? '')
]));
function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stable(value[key])]));
  }
  return value;
}
function objectSha(value) {
  return `sha256:${crypto.createHash('sha256').update(JSON.stringify(stable(value))).digest('hex')}`;
}
const payloadCopy = JSON.parse(JSON.stringify(payload));
delete payloadCopy.payload_sha256;
const computedPayloadSha256 = objectSha(payloadCopy);
if (STRICT_SCHEMA) {
  if (!SHA256_PATTERN.test(String(payload.payload_sha256 || '')) || payload.payload_sha256 !== computedPayloadSha256) {
    throw new Error(`payload_sha256 缺失或不匹配，期望 ${computedPayloadSha256}`);
  }
  if (String(headers['x-openclaw-payload-sha256'] || '') !== computedPayloadSha256) {
    throw new Error('请求头 x-openclaw-payload-sha256 缺失或不匹配');
  }
  if ('shared_asset_root' in payload || 'shared_asset_root' in (payload.defaults || {})) {
    throw new Error('shared_asset_root 必须来自 OPENCLAW_ASSET_SHARED_ROOT，禁止由 Payload 指定');
  }
}

function safeId(value, fallback, maxLength = 120) {
  const cleaned = String(value ?? fallback)
    .normalize('NFKC')
    .replace(/[^a-zA-Z0-9_-]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, maxLength);
  return cleaned || fallback;
}

function clamp(value, min, max, fallback) {
  const number = Number(value);
  return Number.isFinite(number)
    ? Math.min(max, Math.max(min, Math.floor(number)))
    : fallback;
}

function atomicJson(filePath, value) {
  const tmp = `${filePath}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(value, null, 2), 'utf8');
  fs.renameSync(tmp, filePath);
}

function normalizeStringArray(value, fieldName, maxItems = 64) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new Error(`${fieldName} 必须是数组`);
  if (value.length > maxItems) throw new Error(`${fieldName} 不能超过 ${maxItems} 项`);
  const seen = new Set();
  const output = [];
  for (const item of value) {
    const normalized = safeId(item, '', 140);
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    output.push(normalized);
  }
  return output;
}

function normalizeCategory(value) {
  const raw = String(value ?? '').normalize('NFKC').trim().toLowerCase();
  const aliases = {
    role: 'character', character: 'character', '角色': 'character', '人物': 'character',
    animal: 'animal', '动物': 'animal',
    creature: 'creature', monster: 'creature', '生物': 'creature', '异兽': 'creature', '怪物': 'creature',
    scene: 'location', location: 'location', '场景': 'location', '地点': 'location',
    prop: 'prop', object: 'prop', vehicle: 'prop', '道具': 'prop', '载具': 'prop',
    style: 'style', '风格': 'style',
    storyboard: 'storyboard', shot: 'storyboard', '分镜': 'storyboard', '镜头': 'storyboard'
  };
  return aliases[raw] ?? 'other';
}

function resolveSafeFile(rawPath, fieldName) {
  if (typeof rawPath !== 'string' || !rawPath.trim()) {
    throw new Error(`${fieldName} 必须是非空路径`);
  }
  const resolved = path.resolve(rawPath.trim());
  const safeRoot = path.resolve(ROOT) + path.sep;
  if (!resolved.startsWith(safeRoot)) {
    throw new Error(`${fieldName} 超出固定资产根目录`);
  }
  if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) {
    throw new Error(`${fieldName} 不存在或不是文件：${resolved}`);
  }
  const extension = path.extname(resolved).toLowerCase();
  if (!new Set(['.png', '.jpg', '.jpeg', '.webp']).has(extension)) {
    throw new Error(`${fieldName} 格式不受支持：${extension || 'unknown'}`);
  }
  return resolved;
}

function normalizeReferenceImages(value, assetId, maximum) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new Error(`${assetId} 的 reference_images 必须是数组`);
  if (value.length > maximum) {
    throw new Error(`${assetId} 的直接 reference_images 不能超过 ${maximum} 张`);
  }
  const seen = new Set();
  return value.map((rawPath, index) => {
    const resolved = resolveSafeFile(rawPath, `${assetId}.reference_images[${index}]`);
    if (seen.has(resolved)) throw new Error(`${assetId} 存在重复参考图：${resolved}`);
    seen.add(resolved);
    return resolved;
  });
}

function extractHardLocks(prompt, assetId, category) {
  const sceneMode = category === 'location';
  const headingGroups = [
    ['style_lock', ['【STYLE LOCK｜固定原文】']],
    [sceneMode ? 'scene_dna' : 'subject_dna', sceneMode
      ? ['【SCENE DNA / SUBJECT DNA｜固定原文】', '【SCENE DNA｜固定原文】']
      : ['【SCENE DNA / SUBJECT DNA｜固定原文】', '【SUBJECT DNA｜固定原文】']],
    [sceneMode ? 'spatial_lock' : 'structure_lock', sceneMode
      ? ['【SPATIAL LOCK / STRUCTURE LOCK｜固定原文】', '【SPATIAL LOCK｜固定原文】']
      : ['【SPATIAL LOCK / STRUCTURE LOCK｜固定原文】', '【STRUCTURE LOCK｜固定原文】']],
    ['continuity_lock', ['【CONTINUITY LOCK｜固定原文】']]
  ];
  const text = String(prompt || '');
  const locks = {};
  const allAcceptedHeadings = headingGroups.flatMap(([, accepted]) => accepted);
  for (const [key, accepted] of headingGroups) {
    const present = accepted
      .map((heading) => ({ heading, startAt: text.indexOf(heading) }))
      .filter((item) => item.startAt >= 0);
    if (present.length === 0) throw new Error(`${assetId} 缺少四锁标题之一：${accepted.join(' / ')}`);
    if (present.length > 1) throw new Error(`${assetId} 存在冲突的四锁标题：${present.map((item) => item.heading).join(' / ')}`);
    const { heading, startAt } = present[0];
    const contentStart = startAt + heading.length;
    let contentEnd = text.length;
    for (const nextHeading of allAcceptedHeadings) {
      const candidate = text.indexOf(nextHeading, contentStart);
      if (candidate >= 0 && candidate < contentEnd) contentEnd = candidate;
    }
    const nextAny = text.slice(contentStart).match(/\n【[^】]+】/);
    if (nextAny) contentEnd = Math.min(contentEnd, contentStart + nextAny.index);
    const value = text.slice(contentStart, contentEnd).trim();
    if (!value) throw new Error(`${assetId} 四锁内容为空：${heading}`);
    locks[key] = value;
  }
  return locks;
}

function normalizeReferenceInputs(value, assetId) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new Error(`${assetId} 的 reference_inputs 必须是数组`);
  if (value.length > 16) throw new Error(`${assetId} 的 reference_inputs 不能超过16项`);
  return value.map((raw, index) => {
    const input = typeof raw === 'string' ? { asset_id: raw } : raw;
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error(`${assetId}.reference_inputs[${index}] 必须是字符串或对象`);
    }
    const refAssetId = input.asset_id ? safeId(input.asset_id, '', 140) : '';
    const directPath = input.path
      ? resolveSafeFile(input.path, `${assetId}.reference_inputs[${index}].path`)
      : '';
    if ((!refAssetId && !directPath) || (refAssetId && directPath)) {
      throw new Error(`${assetId}.reference_inputs[${index}] 必须且只能填写 asset_id 或 path`);
    }
    return {
      asset_id: refAssetId || null,
      path: directPath || null,
      role: String(input.role ?? 'reference').trim() || 'reference',
      required: input.required !== false,
      approved_only: input.approved_only !== false,
      priority: clamp(input.priority, 0, 999, index + 1),
      notes: String(input.notes ?? '').trim()
    };
  });
}

function hasRunningAsset(runningDir, assetId) {
  if (!fs.existsSync(runningDir)) return false;
  return fs.readdirSync(runningDir)
    .filter((name) => name.endsWith('.json'))
    .some((name) => {
      try {
        const task = JSON.parse(fs.readFileSync(path.join(runningDir, name), 'utf8'));
        return String(task.asset_id ?? '') === String(assetId);
      } catch {
        return false;
      }
    });
}

const projectId = safeId(payload.project_id, 'project', 80);
const jobId = safeId(payload.job_id, `job_${Date.now()}`, 100);
const resumeFailed = payload.resume_failed === true;
const rawDefaults = payload.defaults ?? {};

const configuredGenerationModel = String(rawDefaults.model ?? '').trim();
const inferredImageSlot = /gemini/i.test(configuredGenerationModel)
  ? 'B'
  : /gpt|image/i.test(configuredGenerationModel)
    ? 'C'
    : 'A';
const slotDefinitions = {
  A: {
    provider: 'volcengine_ark',
    model: String(payload.SLOT_A_MODEL ?? (inferredImageSlot === 'A' ? configuredGenerationModel : '')).trim(),
    cost_tier: 'configurable',
    options: {
      image_size: String(payload.SLOT_A_IMAGE_SIZE ?? rawDefaults.image_size ?? '2K').toUpperCase(),
      guidance_scale: 3
    }
  },
  B: {
    provider: 'google_gemini',
    model: String(payload.SLOT_B_MODEL ?? (inferredImageSlot === 'B' ? configuredGenerationModel : '')).trim(),
    cost_tier: 'configurable',
    options: { image_size: String(payload.SLOT_B_IMAGE_SIZE ?? rawDefaults.image_size ?? '2K').toUpperCase() }
  },
  C: {
    provider: 'openai_images',
    model: String(payload.SLOT_C_MODEL ?? (inferredImageSlot === 'C' ? configuredGenerationModel : '')).trim(),
    cost_tier: 'configurable',
    options: {
      quality: String(payload.SLOT_C_QUALITY ?? 'medium').toLowerCase(),
      background: 'opaque',
      output_format: 'png'
    }
  }
};

const activeSlot = String(payload.ACTIVE_IMAGE_SLOT ?? inferredImageSlot).trim().toUpperCase();
const fallbackSlot = String(payload.FALLBACK_IMAGE_SLOT ?? 'NONE').trim().toUpperCase();
const referenceImageSlot = String(
  payload.REFERENCE_IMAGE_SLOT ?? (['B', 'C'].includes(activeSlot) ? activeSlot : 'C')
).trim().toUpperCase();
const allowedSlots = new Set(['A', 'B', 'C']);
if (!allowedSlots.has(activeSlot)) throw new Error('ACTIVE_IMAGE_SLOT 只能填写 A、B 或 C');
if (fallbackSlot !== 'NONE' && !allowedSlots.has(fallbackSlot)) {
  throw new Error('FALLBACK_IMAGE_SLOT 只能填写 NONE、A、B 或 C');
}
if (!['B', 'C'].includes(referenceImageSlot)) {
  throw new Error('REFERENCE_IMAGE_SLOT 只能填写已实现真实参考图注入的 B 或 C');
}

const paidGenerationLimit = clamp(payload.MAX_PAID_GENERATIONS_PER_ASSET, 1, 3, 1);
const maxReferenceImages = clamp(payload.MAX_REFERENCE_IMAGES, 1, 2, 2);
const allowProvisionalReferences = payload.ALLOW_PROVISIONAL_REFERENCES === true;

function validateSlot(slotId) {
  const route = slotDefinitions[slotId];
  if (!route.model || /REPLACE|替换|请填写/i.test(route.model)) {
    throw new Error(`模型槽位 ${slotId} 缺少真实 Model ID`);
  }
  return route;
}

function buildVisualRoutePlan(requiresReferences) {
  if (requiresReferences) {
    const referenceRoute = validateSlot(referenceImageSlot);
    return Array.from({ length: paidGenerationLimit }, (_, index) => ({
      attempt: index + 1,
      route_id: `slot_${referenceImageSlot}`,
      slot_id: referenceImageSlot,
      reference_capable: true,
      ...referenceRoute
    }));
  }
  const primary = validateSlot(activeSlot);
  const routes = [{
    attempt: 1,
    route_id: `slot_${activeSlot}`,
    slot_id: activeSlot,
    reference_capable: ['B', 'C'].includes(activeSlot),
    ...primary
  }];
  if (paidGenerationLimit <= 1) return routes;
  const retrySlot = fallbackSlot === 'NONE' ? activeSlot : fallbackSlot;
  const retry = validateSlot(retrySlot);
  while (routes.length < paidGenerationLimit) {
    routes.push({
      attempt: routes.length + 1,
      route_id: `slot_${retrySlot}`,
      slot_id: retrySlot,
      reference_capable: ['B', 'C'].includes(retrySlot),
      ...retry
    });
  }
  return routes;
}

const configuredReviewModel = String(rawDefaults.review_model ?? '').trim();
const reviewSlotDefinitions = {
  G: { provider: 'google_gemini', model: String(payload.REVIEW_SLOT_G_MODEL ?? configuredReviewModel).trim() },
  O: { provider: 'openai_vision', model: String(payload.REVIEW_SLOT_O_MODEL ?? '').trim() },
  V: { provider: 'volcengine_vision', model: String(payload.REVIEW_SLOT_V_MODEL ?? '').trim() }
};
const activeReviewSlot = String(payload.ACTIVE_REVIEW_SLOT ?? 'G').trim().toUpperCase();
if (!['G', 'O', 'V'].includes(activeReviewSlot)) {
  throw new Error('ACTIVE_REVIEW_SLOT 只能填写 G、O 或 V');
}
const selectedReviewRoute = reviewSlotDefinitions[activeReviewSlot];
if (!selectedReviewRoute.model || /REPLACE|替换|请填写/i.test(selectedReviewRoute.model)) {
  throw new Error(`质检槽位 ${activeReviewSlot} 缺少真实 Model ID`);
}
const reviewApiMaxRetries = clamp(payload.MAX_REVIEW_API_RETRIES, 1, 5, 3);

const defaults = {
  model: String(rawDefaults.model ?? 'doubao-seedream-4-0-250828'),
  aspect_ratio: String(rawDefaults.aspect_ratio ?? '16:9'),
  image_size: String(rawDefaults.image_size ?? '2K').toUpperCase(),
  review_model: String(rawDefaults.review_model ?? 'gemini-2.5-flash'),
  review_min_score: clamp(rawDefaults.review_min_score, 0, 100, 80),
  review_max_retries: clamp(rawDefaults.review_max_retries, 0, 3, 2),
  max_image_generations: clamp(rawDefaults.max_image_generations, 1, 6, 3)
};
const categoryDefaultRatios = {
  location: '16:9', storyboard: '16:9',
  character: '9:16', animal: '9:16', creature: '9:16', prop: '9:16',
  style: defaults.aspect_ratio, other: defaults.aspect_ratio
};
const allowedRatios = new Set(['1:1', '2:3', '3:2', '3:4', '4:3', '4:5', '5:4', '9:16', '16:9', '21:9']);
const allowedSizes = new Set(['1K', '2K', '4K']);
const seenIds = new Set();
const seenFiles = new Set();

let assets = payload.assets.map((asset, index) => {
  if (!asset || typeof asset !== 'object' || Array.isArray(asset)) {
    throw new Error(`assets[${index}] 必须是对象`);
  }
  const assetId = safeId(asset.asset_id, `ASSET_${String(index + 1).padStart(3, '0')}`);
  if (seenIds.has(assetId)) throw new Error(`重复 asset_id：${assetId}`);
  seenIds.add(assetId);

  const filenameBase = safeId(String(asset.filename ?? assetId).replace(/\.[^.]+$/, ''), assetId);
  const filename = `${filenameBase}.png`;
  if (seenFiles.has(filename)) throw new Error(`重复 filename：${filename}`);
  seenFiles.add(filename);

  const promptZh = typeof asset.prompt_zh === 'string' ? asset.prompt_zh.trim() : '';
  const promptEn = typeof asset.prompt_en === 'string' ? asset.prompt_en.trim() : '';
  if (!promptZh && !promptEn) throw new Error(`${assetId} 缺少 prompt_zh / prompt_en`);

const category = normalizeCategory(asset.category ?? asset.asset_type);
  const assetMetadata = asset.metadata && typeof asset.metadata === 'object' && !Array.isArray(asset.metadata)
    ? asset.metadata
    : {};
  const sceneIds = normalizeStringArray(asset.scene_ids ?? assetMetadata.scene_ids, `${assetId}.scene_ids`, 128);
  const sceneId = String(asset.scene_id ?? assetMetadata.scene_id ?? '').trim();
  const locationId = String(asset.location_id ?? assetMetadata.location_id ?? '').trim();
  const subLocationId = String(asset.sub_location_id ?? assetMetadata.sub_location_id ?? '').trim();
  const locationAssetId = String(asset.location_asset_id ?? assetMetadata.location_asset_id ?? assetId).trim();
  if (STRICT_SCHEMA) {
    if (!promptZh.startsWith('【PORTABLE HARD LOCK｜独立可用｜禁止删减】')) {
      throw new Error(`${assetId} 缺少 PORTABLE HARD LOCK 固定开头`);
    }
    const canonicalLocks = extractHardLocks(promptZh, assetId, category);
    const computedLockHash = crypto.createHash('sha256').update(JSON.stringify(stable(canonicalLocks))).digest('hex');
    const submittedLockHash = String(asset.lock_hash || '');
    if (!new Set([computedLockHash, `sha256:${computedLockHash}`]).has(submittedLockHash)) {
      throw new Error(`${assetId} lock_hash 缺失或不匹配，期望 ${computedLockHash}`);
    }
    if (!String(asset.lock_id || '').trim()) throw new Error(`${assetId} 缺少 lock_id`);
    const renderAsset = ['character', 'creature', 'location', 'prop'].includes(category);
    if (renderAsset) {
      if (asset.asset_role !== 'video_reference') throw new Error(`${assetId} asset_role 必须为 video_reference`);
      if (!String(asset.asset_kind || '').trim()) throw new Error(`${assetId} 缺少 asset_kind`);
      if (!String(asset.angle_id || '').trim()) throw new Error(`${assetId} 缺少 angle_id`);
      if (asset.layout_type !== 'single_view_clean') throw new Error(`${assetId} layout_type 必须为 single_view_clean`);
      if (asset.contains_multiple_independent_assets !== false) {
        throw new Error(`${assetId} contains_multiple_independent_assets 必须为 false`);
      }
    }
    if (category === 'location') {
      if (sceneIds.length === 0) throw new Error(`${assetId} 缺少 scene_ids[]`);
      if (!locationId) throw new Error(`${assetId} 缺少 location_id`);
      if (!subLocationId) throw new Error(`${assetId} 缺少 sub_location_id`);
      if (!locationAssetId) throw new Error(`${assetId} 缺少 location_asset_id`);
    }
    if (String(asset.generation_stage || '').toLowerCase() === 'shot' && !sceneId) {
      throw new Error(`${assetId} shot 资产缺少 scene_id`);
    }
  }
  const directReferences = normalizeReferenceImages(asset.reference_images, assetId, maxReferenceImages);
  const referenceInputs = normalizeReferenceInputs(asset.reference_inputs, assetId);
  const requiresReferences = directReferences.length > 0 || referenceInputs.length > 0;
  const requestedMaximum = clamp(asset.max_image_generations, 1, paidGenerationLimit, paidGenerationLimit);
  const fullRoutePlan = buildVisualRoutePlan(requiresReferences);
  const maxImageGenerations = Math.min(paidGenerationLimit, requestedMaximum, fullRoutePlan.length);
  const modelRoutePlan = fullRoutePlan.slice(0, maxImageGenerations).map((route) => ({ ...route }));

  let aspectRatio = String(asset.aspect_ratio ?? categoryDefaultRatios[category] ?? defaults.aspect_ratio);
  if (!allowedRatios.has(aspectRatio)) aspectRatio = categoryDefaultRatios[category] ?? '16:9';
  let imageSize = String(asset.image_size ?? defaults.image_size).toUpperCase();
  if (!allowedSizes.has(imageSize)) imageSize = '2K';

  const dependsOn = normalizeStringArray(asset.depends_on, `${assetId}.depends_on`, 128);
  if (dependsOn.includes(assetId)) throw new Error(`${assetId} 不能依赖自身`);

  return {
    original_index: index + 1,
    asset_index: index + 1,
    asset_id: assetId,
    parent_asset_id: asset.parent_asset_id ? safeId(asset.parent_asset_id, '', 140) : null,
    family_id: asset.family_id ? safeId(asset.family_id, '', 140) : null,
    asset_code: String(asset.asset_code ?? '').trim() || null,
    generation_stage: ['anchor', 'derived', 'shot'].includes(String(asset.generation_stage ?? '').toLowerCase())
      ? String(asset.generation_stage).toLowerCase()
      : 'derived',
    category,
asset_type: category,
    asset_role: String(asset.asset_role ?? '').trim() || null,
    asset_kind: String(asset.asset_kind ?? category).trim() || category,
    angle_id: String(asset.angle_id ?? '').trim() || null,
    layout_type: String(asset.layout_type ?? '').trim() || null,
    contains_multiple_independent_assets: asset.contains_multiple_independent_assets === true,
    contains_text_or_annotations: asset.contains_text_or_annotations === true,
    video_reference_eligible: asset.video_reference_eligible !== false,
    reference_scope: String(asset.reference_scope ?? '').trim() || null,
    scene_ids: sceneIds,
    scene_id: sceneId ? safeId(sceneId, '', 140) : null,
    location_id: locationId ? safeId(locationId, '', 140) : null,
    sub_location_id: subLocationId ? safeId(subLocationId, '', 140) : null,
    location_asset_id: locationAssetId ? safeId(locationAssetId, '', 140) : null,
    payload_sha256: computedPayloadSha256,
    name: String(asset.name ?? assetId),
    filename,
    prompt_zh: promptZh,
    prompt_en: promptEn,
    negative_prompt: String(asset.negative_prompt ?? '').trim(),
    model: modelRoutePlan[0].model,
    model_route_plan: modelRoutePlan,
    aspect_ratio: aspectRatio,
    image_size: imageSize,
    depends_on: dependsOn,
    reference_inputs: referenceInputs,
    reference_images: directReferences,
    requires_reference_images: requiresReferences,
    max_reference_images: maxReferenceImages,
    allow_provisional_references: asset.allow_provisional_references === true || allowProvisionalReferences,
    anchor_roles: normalizeStringArray(asset.anchor_roles, `${assetId}.anchor_roles`, 32),
    lock_id: String(asset.lock_id ?? '').trim() || null,
    lock_hash: String(asset.lock_hash ?? '').trim() || null,
    prompt_policy: String(asset.prompt_policy ?? 'PORTABLE_HARD_LOCK').trim(),
    metadata: asset.metadata ?? {},
    max_image_generations: maxImageGenerations,
    review_slot_id: activeReviewSlot,
    review_provider: selectedReviewRoute.provider,
    review_model: selectedReviewRoute.model,
    review_route_profile: `review_slot_${activeReviewSlot}`,
    review_min_score: clamp(asset.review_min_score, 0, 100, defaults.review_min_score),
    review_max_retries: Math.min(
      Math.max(0, maxImageGenerations - 1),
      clamp(asset.review_max_retries, 0, 3, defaults.review_max_retries)
    )
  };
});

// 对同一任务内依赖做拓扑排序；跨任务依赖由 Worker 通过项目级 Registry 解析。
const assetMap = new Map(assets.map((asset) => [asset.asset_id, asset]));
const indegree = new Map(assets.map((asset) => [asset.asset_id, 0]));
const adjacency = new Map(assets.map((asset) => [asset.asset_id, []]));
for (const asset of assets) {
  for (const dependency of asset.depends_on) {
    if (!assetMap.has(dependency)) continue;
    indegree.set(asset.asset_id, indegree.get(asset.asset_id) + 1);
    adjacency.get(dependency).push(asset.asset_id);
  }
}
const ready = assets.filter((asset) => indegree.get(asset.asset_id) === 0)
  .sort((a, b) => a.original_index - b.original_index)
  .map((asset) => asset.asset_id);
const sortedIds = [];
while (ready.length) {
  const id = ready.shift();
  sortedIds.push(id);
  for (const child of adjacency.get(id)) {
    indegree.set(child, indegree.get(child) - 1);
    if (indegree.get(child) === 0) {
      ready.push(child);
      ready.sort((a, b) => assetMap.get(a).original_index - assetMap.get(b).original_index);
    }
  }
}
if (sortedIds.length !== assets.length) {
  const cycleNodes = assets.filter((asset) => !sortedIds.includes(asset.asset_id)).map((asset) => asset.asset_id);
  throw new Error(`DEPENDENCY_CYCLE_DETECTED：${cycleNodes.join(', ')}`);
}
assets = sortedIds.map((id, index) => ({ ...assetMap.get(id), asset_index: index + 1 }));

const outputDir = path.resolve(ROOT, projectId, jobId);
const safeRoot = path.resolve(ROOT) + path.sep;
if (!outputDir.startsWith(safeRoot)) throw new Error('任务输出目录超出固定资产根目录');
const dirs = {
  queue: path.join(outputDir, '_queue'),
  running: path.join(outputDir, '_running'),
  doneQueue: path.join(outputDir, '_queue_done'),
  status: path.join(outputDir, '_status'),
  statusHistory: path.join(outputDir, '_status_history'),
  candidates: path.join(outputDir, '_candidates'),
  rejected: path.join(outputDir, '_rejected'),
  logs: path.join(outputDir, '_logs'),
  dependencyState: path.join(outputDir, '_dependency_state')
};
fs.mkdirSync(outputDir, { recursive: true });
for (const dir of Object.values(dirs)) fs.mkdirSync(dir, { recursive: true });

const routingSnapshot = {
  schema_version: '2.0',
  selection_mode: 'visual_credential_slots',
  active_profile: `visual_slot_${activeSlot}`,
  active_slot: activeSlot,
  fallback_slot: fallbackSlot,
  reference_image_slot: referenceImageSlot,
  max_reference_images: maxReferenceImages,
  max_paid_generations_per_asset: paidGenerationLimit,
  slots: Object.fromEntries(Object.entries(slotDefinitions).map(([id, value]) => [id, { provider: value.provider, model: value.model }])),
  cost_guard: {
    allow_request_to_raise_budget: false,
    fallback_on_auth_error: false,
    fallback_on_request_error: true,
    timeout_unknown_retry_limit: 1,
    rate_limit_retry_limit: 5,
    use_best_candidate_when_exhausted: true
  }
};
const reviewRoutingSnapshot = {
  schema_version: '1.1',
  selection_mode: 'visual_credential_slots',
  active_slot: activeReviewSlot,
  provider: selectedReviewRoute.provider,
  model: selectedReviewRoute.model,
  max_api_retries: reviewApiMaxRetries,
  slots: reviewSlotDefinitions
};
const referencePolicy = {
  approved_only_default: !allowProvisionalReferences,
  allow_provisional_references: allowProvisionalReferences,
  registry_path: path.resolve(ROOT, projectId, 'reference_registry.json'),
  maximum_images_per_request: maxReferenceImages
};

const jobCore = {
  schema_version: '3.1',
  input_schema_version: String(payload.schema_version ?? 'legacy'),
  payload_sha256: computedPayloadSha256,
  project_id: projectId,
  job_id: jobId,
  source: String(payload.source ?? 'openclaw'),
  defaults,
  model_routing: routingSnapshot,
  review_routing: reviewRoutingSnapshot,
  reference_policy: referencePolicy,
  expected_count: assets.length,
  assets
};
const jobHash = crypto.createHash('sha256').update(JSON.stringify(jobCore)).digest('hex');
const jobPath = path.join(outputDir, 'job.json');
if (fs.existsSync(jobPath)) {
  const existingJob = JSON.parse(fs.readFileSync(jobPath, 'utf8'));
  if (existingJob.job_hash !== jobHash) {
    throw new Error(`相同 project_id/job_id 已存在不同资产任务：${projectId}/${jobId}`);
  }
} else {
  atomicJson(jobPath, { ...jobCore, job_hash: jobHash, created_at: new Date().toISOString(), updated_at: new Date().toISOString() });
}

atomicJson(path.join(outputDir, 'asset_dependency_graph.json'), {
  schema_version: '1.0',
  project_id: projectId,
  job_id: jobId,
  topological_order: assets.map((asset) => asset.asset_id),
  nodes: assets.map((asset) => ({
    asset_id: asset.asset_id,
    generation_stage: asset.generation_stage,
    depends_on: asset.depends_on,
    reference_inputs: asset.reference_inputs
  }))
});
atomicJson(path.join(outputDir, 'reference_plan.json'), {
  schema_version: '1.0',
  project_id: projectId,
  job_id: jobId,
  registry_path: referencePolicy.registry_path,
  assets: assets.map((asset) => ({
    asset_id: asset.asset_id,
    requires_reference_images: asset.requires_reference_images,
    reference_inputs: asset.reference_inputs,
    direct_reference_images: asset.reference_images,
    anchor_roles: asset.anchor_roles
  }))
});

let queuedCount = 0;
let pendingCount = 0;
let reusedCount = 0;
let failedResetCount = 0;
for (const asset of assets) {
  const statusPath = path.join(dirs.status, `${asset.asset_id}.json`);
  const queuePath = path.join(dirs.queue, `${asset.asset_id}.json`);
  const doneQueuePath = path.join(dirs.doneQueue, `${asset.asset_id}.json`);
  if (fs.existsSync(statusPath)) {
    const record = JSON.parse(fs.readFileSync(statusPath, 'utf8'));
    const isFailure = !['accepted', 'accepted_fallback', 'accepted_fallback_unreviewed'].includes(record.final_status);
    if (!isFailure || !resumeFailed) {
      reusedCount += 1;
      continue;
    }
    fs.renameSync(statusPath, path.join(dirs.statusHistory, `${asset.asset_id}_${Date.now()}.json`));
    failedResetCount += 1;
  }
  if (fs.existsSync(queuePath) || hasRunningAsset(dirs.running, asset.asset_id)) {
    pendingCount += 1;
    continue;
  }
  if (fs.existsSync(doneQueuePath)) {
    fs.renameSync(doneQueuePath, queuePath);
    pendingCount += 1;
    continue;
  }
  atomicJson(queuePath, {
    schema_version: '3.1',
    continuity_mode: true,
    payload_sha256: computedPayloadSha256,
    project_id: projectId,
    job_id: jobId,
    output_dir: outputDir,
    reference_registry_path: referencePolicy.registry_path,
    ...asset,
    retry_count: 0,
    image_generation_count: 0,
    review_retry_count: 0,
    review_api_retry_count: 0,
    review_api_max_retries: reviewApiMaxRetries,
    qa_feedback: '',
    review_history: [],
    worker_execution_count: 0,
    not_before: 0,
    queued_at: new Date().toISOString()
  });
  queuedCount += 1;
}

return [{
  json: {
    event: 'n8n_asset_job_queued',
    schema_version: '3.0',
    continuity_mode: true,
    project_id: projectId,
    job_id: jobId,
    payload_sha256: computedPayloadSha256,
    expected_count: assets.length,
    queued_count: queuedCount,
    pending_count: pendingCount,
    reused_count: reusedCount,
    failed_reset_count: failedResetCount,
    dependency_graph_filename: 'asset_dependency_graph.json',
    reference_plan_filename: 'reference_plan.json',
    reference_registry_path: referencePolicy.registry_path,
    reference_image_slot: referenceImageSlot,
    max_reference_images: maxReferenceImages,
    status: 'queued',
    message: '连续资产任务已按依赖顺序写入文件队列；参考图资产将自动路由到槽位 C'
  }
}];
